// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OrganizationFinalExecutionEvidence) predicate.OrganizationFinalExecutionEvidence {
	return predicate.OrganizationFinalExecutionEvidence(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OrganizationFinalExecutionEvidence) predicate.OrganizationFinalExecutionEvidence {
	return predicate.OrganizationFinalExecutionEvidence(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OrganizationFinalExecutionEvidence) predicate.OrganizationFinalExecutionEvidence {
	return predicate.OrganizationFinalExecutionEvidence(sql.NotPredicates(p))
}
